from json import dumps


class Tree:
    def __init__(self, label, children=None):
        self.label = label
        self.children = children if children is not None else []

    def __dict__(self):
        return {self.label: [c.__dict__() for c in sorted(self.children)]}

    def __str__(self, indent=None):
        return dumps(self.__dict__(), indent=indent)

    def __lt__(self, other):
        return self.label < other.label

    def __eq__(self, other):
        return self.__dict__() == other.__dict__()

    def from_pov(self, from_node):
        tree = self._clone()
        return tree._reroot(from_node)

    def _clone(self):
        return Tree(self.label, [child._clone() for child in self.children])

    def path_to(self, from_node, to_node):
        tree = self.from_pov(from_node)
        path = tree._label_path(to_node)
        if path is None:
            raise ValueError("No path found")
        return path

    def _reroot(self, from_node):
        if self.label == from_node:
            return self

        for child in list(self.children):
            try:
                new_root = child._reroot(from_node)
            except ValueError:
                continue

            self.children.remove(child)
            child.children.append(self)
            return new_root

        raise ValueError("Tree could not be reoriented")

    def _label_path(self, target):
        if self.label == target:
            return [self.label]

        for child in self.children:
            path = child._label_path(target)
            if path is not None:
                return [self.label] + path

        return None

